data.arguments:
{"command":"# Check for llvm-symbolizer in common locations
$paths = @(
    "$env:ANDROID_NDK_ROOT",
    "$env:ANDROID_HOME\ndk",
    "C:\Android\ndk",
    "C:\Program Files\LLVM\bin",
    "C:\Program Files (x86)\LLVM\bin"
)
foreach ($p in $paths) {
    if ($p -and (Test-Path $p)) {
        Get-ChildItem -Recurse -Filter "llvm-symbolizer*" $p -ErrorAction SilentlyContinue | Select-Object FullName
    }
}
# Also check PATH-adjacent locations
Get-Command llvm-symbolizer* -ErrorAction SilentlyContinue | Select-Object Source","description":"Search for llvm-symbolizer in common locations"}

{"command":"# Check for llvm-symbolizer in common locations
$candidates = @(
    (Get-Command llvm-symbolizer -ErrorAction SilentlyContinue)?.Source,
    (Get-Command llvm-symbolizer-14 -ErrorAction SilentlyContinue)?.Source
)
# Check NDK paths
$ndkRoots = @($env:ANDROID_NDK_ROOT, $env:ANDROID_HOME) | Where-Object { $_ }
foreach ($root in $ndkRoots) {
    Get-ChildItem "$root\ndk\*\toolchains\llvm\prebuilt\*\bin\llvm-symbolizer.exe" -ErrorAction SilentlyContinue | ForEach-Object { $candidates += $_.FullName }
}
$candidates | Where-Object { $_ } | Select-Object -Unique","description":"Search for llvm-symbolizer in PATH and NDK"}

{"command":"# Check Android NDK and common paths
$ndkPaths = @(
    $env:ANDROID_NDK_ROOT,
    $env:ANDROID_NDK_HOME,
    (Join-Path $env:ANDROID_HOME "ndk" -ErrorAction SilentlyContinue)
) | Where-Object { $_ }

foreach ($p in $ndkPaths) {
    Write-Host "NDK path: $p"
    Get-ChildItem -Path $p -Recurse -Filter "llvm-symbolizer*" -ErrorAction SilentlyContinue | Select-Object -First 3 FullName
}

# Also check LLVM in common Windows locations
Get-ChildItem "C:\Program Files\LLVM\bin\llvm-symbolizer*" -ErrorAction SilentlyContinue | Select-Object FullName","description":"Search for llvm-symbolizer in NDK and common paths"}
